n=17; center=8
out=[[0]*n for _ in range(n)]
for r in range(n):
    if r<=center:
        for c in {center-r, center+r}:
            out[r][c]=2
    lo=max(0,center-r); hi=min(n-1,center+r)
    for c in range(lo,hi+1):
        if (c-r-center)%4==0 and out[r][c]==0:
            out[r][c]=1
print(out)
print('\n'.join(' '.join(map(str,row)) for row in out))

